4363	        let index = match groups.iter().position(|g| g.0 == identity) {
4364	            Some(k) => k,
4365	            None => {
4366	                groups.push((
4367	                    identity,
4368	                    prepare_group(source).map(Arc::new),
4369	                    GroupCache::default(),
4370	                ));
4371	                groups.len() - 1
4372	            }
4373	        };
4374	        let (_, group, cache) = &mut groups[index];
4375	        let group = match group {
4376	            Ok(g) => g.clone(),
4377	            Err((refusal, geometry)) => {
4378	                out.push(CaseOutcome::Refused {
4379	                    refusal: refusal.clone(),
4380	                    geometry: geometry.clone(),
4381	                });
