 688	    pub(crate) fn offer(
 689	        &mut self,
 690	        ctx64: &mut WideContext<4>,
 691	        ctx16: &mut WideContext<16>,
 692	        num: ExactWideSum,
 693	        den: ExactWideSum,
 694	    ) -> Result<(), AttemptStop> {
 695	        let key = approximate_ratio(ctx64, &num, &den)?.to_bits();
 696	        let seq = self.offered;
 697	        self.offered += 1;
 698	        let better = match (self.best, self.direction) {
 699	            (None, _) => true,
 700	            (Some(b), Direction::Up) => key > b,
 701	            (Some(b), Direction::Down) => key < b,
 702	        };
 703	        if better {
 704	            self.best = Some(key);
 705	            self.lazy.retain(|row| in_window(row.2, key));
 706	            if self.lazy.is_empty() {
 707	                self.lazy = Vec::new();
 708	            }
 709	            self.table.retain(|entry| in_window(entry.0, key));
 710	        }
 711	        if self.best.is_some_and(|b| in_window(key, b)) {
 712	            if self.lazy.len() >= self.limit {
 713	                self.collapse(ctx16);
 714	            }
 715	            self.lazy.push((num, den, key, seq));
 716	        }
 717	        Ok(())
 718	    }
