 720	    /// Evaluates the unevaluated rows exactly (a refusal is recorded, not
 721	    /// returned) and releases their memory.
 722	    pub(crate) fn collapse(&mut self, ctx16: &mut WideContext<16>) {
 723	        let lazy = std::mem::take(&mut self.lazy);
 724	        if lazy.is_empty() {
 725	            return;
 726	        }
 727	        for (num, den, key, seq) in &lazy {
 728	            let outcome = match directed_ratio(ctx16, num, den, self.direction) {
 729	                Ok(value) => Evaluated::Ratio(value),
 730	                Err(stop) => Evaluated::Refused { seq: *seq, stop },
 731	            };
 732	            self.table.push((*key, outcome));
 733	        }
 734	        drop(lazy);
 735	        self.prune();
 736	    }
