 738	    /// Keeps the entries no other entry dominates: sorted nearest the best
 739	    /// first (within a key, the most decisive first), an entry stays only if it
 740	    /// decides `finish` ahead of every entry kept before it.
 741	    fn prune(&mut self) {
 742	        let direction = self.direction;
 743	        self.table.sort_by(|a, b| {
 744	            let by_key = match direction {
 745	                Direction::Up => b.0.cmp(&a.0),
 746	                Direction::Down => a.0.cmp(&b.0),
 747	            };
 748	            by_key.then_with(|| {
 749	                if a.1.beats(&b.1, direction) {
 750	                    CmpOrdering::Less
 751	                } else if b.1.beats(&a.1, direction) {
 752	                    CmpOrdering::Greater
 753	                } else {
 754	                    CmpOrdering::Equal
 755	                }
 756	            })
 757	        });
 758	        let mut kept: Vec<(u64, Evaluated)> = Vec::new();
 759	        for entry in self.table.drain(..) {
 760	            if kept
 761	                .last()
 762	                .is_none_or(|last| entry.1.beats(&last.1, direction))
 763	            {
 764	                kept.push(entry);
 765	            }
 766	        }
 767	        kept.shrink_to_fit();
 768	        self.table = kept;
 769	    }
