 771	    pub(crate) fn finish(self, ctx16: &mut WideContext<16>) -> Result<Option<f64>, AttemptStop> {
 772	        let mut best: Option<f64> = None;
 773	        let mut refused: Option<(u64, AttemptStop)> = None;
 774	        for (_, outcome) in self.table {
 775	            match outcome {
 776	                Evaluated::Ratio(value) => best = Some(extreme(best, value, self.direction)),
 777	                Evaluated::Refused { seq, stop } => {
 778	                    if refused.as_ref().is_none_or(|r| seq < r.0) {
 779	                        refused = Some((seq, stop));
 780	                    }
 781	                }
 782	            }
 783	        }
 784	        // A refusal among the evaluated rows came before every unevaluated row.
 785	        if let Some((_, stop)) = refused {
 786	            return Err(stop);
 787	        }
 788	        for (num, den, _, _) in &self.lazy {
 789	            let exact = directed_ratio(ctx16, num, den, self.direction)?;
 790	            best = Some(extreme(best, exact, self.direction));
 791	        }
 792	        Ok(best)
 793	    }
