1937	fn scales_at<const M: usize>(
1938	    ctx: &mut WideContext<M>,
1939	    layout: &[QuantityMeta],
1940	    values: &[Wide<M>],
1941	    extents: &[f64],
1942	    skip: &[bool],
1943	) -> Result<Vec<[Wide<M>; 4]>, AttemptStop>
1944	where
1945	    Wide<M>: SupportedWidth,
1946	{
1947	    let zero = Wide::<M>::ZERO;
1948	    let mut s = vec![[zero; 4]; extents.len()];
1949	    for ((meta, v), &skipped) in layout.iter().zip(values).zip(skip) {
1950	        if meta.input_derived || skipped {
1951	            continue;
1952	        }
1953	        let slot = &mut s[meta.body as usize][meta.kind.index()];
1954	        if v.abs().cmp_value(slot) == CmpOrdering::Greater {
1955	            *slot = v.abs();
1956	        }
1957	    }
1958	    let max = |a: Wide<M>, b: Wide<M>| {
1959	        if b.cmp_value(&a) == CmpOrdering::Greater {
1960	            b
1961	        } else {
1962	            a
1963	        }
1964	    };
1965	    let mut out = Vec::with_capacity(extents.len());
1966	    for (body, &extent) in extents.iter().enumerate() {
1967	        let [tr, ro, fo, mo] = s[body];
1968	        if extent == 0.0 {
1969	            out.push([tr, ro, fo, mo]);
1970	            continue;
1971	        }
1972	        let lb = Wide::<M>::from_f64(extent)?;
1973	        out.push([
1974	            max(tr, ctx.mul(&lb, &ro)?),
1975	            max(ro, ctx.div(&tr, &lb)?),
1976	            max(fo, ctx.div(&mo, &lb)?),
1977	            max(mo, ctx.mul(&lb, &fo)?),
1978	        ]);
1979	    }
